  ('P2','CRS','CRS-T1','CRS-T1-O1','Which of these was made by God?','[{"id": "a", "text": "A motor car"}, {"id": "b", "text": "A plastic chair"}, {"id": "c", "text": "A big tree"}, {"id": "d", "text": "A mobile phone"}]','{"correct": ["c"], "explanation": "God created trees and other plants, while people build cars and phones."}',0.3,'{P2,CRS,nerdc-quiz-seed-v2}'),
  ('P2','CRS','CRS-T1','CRS-T1-O1','God created the fishes to live in the?','[{"id": "a", "text": "Water"}, {"id": "b", "text": "Fire"}, {"id": "c", "text": "Cupboard"}, {"id": "d", "text": "Pot"}]','{"correct": ["a"], "explanation": "God made fishes to live and swim in the water."}',0.2,'{P2,CRS,nerdc-quiz-seed-v2}'),
