  ('P3','CIV','CIV-T3','CIV-T3-O1','The animal found on the Nigerian Coat of Arms is the:','[{"id": "a", "text": "lion"}, {"id": "b", "text": "elephant"}, {"id": "c", "text": "eagle"}, {"id": "d", "text": "goat"}]','{"correct": ["c"], "explanation": "An eagle sits at the top of the Nigerian Coat of Arms."}',0.3,'{P3,CIV,nerdc-quiz-seed-v2}'),
  ('P3','CIV','CIV-T3','CIV-T3-O1','The white part of the Nigerian flag stands for:','[{"id": "a", "text": "peace"}, {"id": "b", "text": "war"}, {"id": "c", "text": "anger"}, {"id": "d", "text": "fear"}]','{"correct": ["a"], "explanation": "The white colour on the flag stands for peace."}',0.3,'{P3,CIV,nerdc-quiz-seed-v2}'),
  ('P3','CIV','CIV-T3','CIV-T3-O1','The green part of the Nigerian flag stands for our:','[{"id": "a", "text": "rivers"}, {"id": "b", "text": "farmland and forests"}, {"id": "c", "text": "houses"}, {"id": "d", "text": "roads"}]','{"correct": ["b"], "explanation": "Green stands for Nigeria''s rich farmland and forests."}',0.3,'{P3,CIV,nerdc-quiz-seed-v2}'),
